+    if (ssid[0]) {
+        dm_net_wifi_connect_start(ssid, psk[0] ? psk : NULL);
+        if (wifi_status_lbl)
+            lv_label_set_text_fmt(wifi_status_lbl, "正在连接 %s…", ssid);
