237	static void wifi_poll_cb(lv_timer_t *timer)
238	{
239	    (void)timer;
240	
241	    /* 扫描失败（驱动忙/超时）：提示重试，避免永远卡"扫描中…" */
242	    if (dm_net_wifi_scan_failed() && wifi_status_lbl) {
243	        lv_label_set_text(wifi_status_lbl, "扫描失败，请点\"重新扫描\"重试");
244	    } else if (dm_net_wifi_scan_done() && wifi_list_cont) {
245	        wifi_rebuild_list();
246	    }
247	
248	    int st = dm_net_wifi_connect_state();
249	    if (st != wifi_last_conn_state && wifi_status_lbl) {
250	        if (st == 2) {   /* 连接成功：记住配置 + 刷新状态栏/清单 */
251	            char cur[33] = {0};
252	            dm_net_wifi_cur_ssid(cur, sizeof(cur));
253	            dm_net_wifi_save_conf(cur, NULL);   /* psk 已由 dm_net 线程保存 */
254	            lv_label_set_text_fmt(wifi_status_lbl, "已连接 %s", cur);
255	            wifi_rebuild_list();
256	            dm_net_status_refresh();
257	        } else if (st == 3) {
258	            lv_label_set_text(wifi_status_lbl,
259	                              "连接失败：密码错误或无法连接");
260	        }
261	        wifi_last_conn_state = st;
262	    }
263	}
